import re

def is_pass_complex(password):
    complexity = 0
    if len(password) >= 12:
        complexity += 1
    if any(c.islower() for c in password):
        complexity += 1
    if any(c.isupper() for c in password):
        complexity += 1
    if any(c.isdigit() for c in password):
        complexity += 1
    if re.search(r'[!\@\#\$\%\^\&\*]', password):
        complexity += 1
    return complexity >= 3

def get_password_streak(password):
    streak = 1
    max_streak = 0
    prev_char_type = type(password[0])
    for char in password[1:]:
        cur_char_type = type(char)
        if char == prev_char_type:
            streak += 1
        else:
            streak = 1
            prev_char_type = cur_char_type
        max_streak = max(max_streak, streak)
    return max_streak
```

