    rows = []
    with open(fpath) as f:
        reader = csv.DictReader(f)
        for row in reader:
            rows.append(row)

    return {'columns': reader.fieldnames,
            'data': rows}

def extract_values_by_keys(data_dict, keys):
    result = defaultdict(list)
    for key in keys:
        if key in data_dict['columns']:
            for row in data_dict['data']:
                result[key].append(row[key])
        else:
            result[key] = [None] * len(data_dict['data'])
    return result

def extract_values_by_keys_from_file(fpath, keys):
    data_dict = read_csv(fpath)
    return extract_values_by_keys(data_dict, keys)

csv_path = 'data.csv'
keys_to_extract = ['Name', 'Age']

values = extract_values_by_keys_from_file(csv_path, keys_to_extract)
for key, values in values.items():
    print(f"{key}: {values}")
```

