import os

def get_file_size(path):
    return os.path.getsize(path)

def get_directory_size(path):
    total = 0
    for entry in os.scandir(path):
        if entry.is_file():
            total += get_file_size(entry)
        elif entry.is_dir():
            total += get_directory_size(entry.path)
    return total

def create_file_report(path):
    return f'File: {path}\nSize: {get_file_size(path)} bytes'

def create_directory_report(path):
    size = get_directory_size(path)
    files = []
    dirs = []
    for entry in os.scandir(path):
        if entry.is_file():
            files.append(entry.name)
        elif entry.is_dir():
            dirs.append(entry.name)
    return f'''
    Directory: {path} 
    Size: {size} bytes
    Number of Files: {len(files)}
    Number of Subdirectories: {len(dirs)}
    Files: {', '.join(files)}
    Directories: {', '.join(dirs)}
    '''

if __name__ == '__main__':
    path = '/var/log'
    report = create_directory_report(path)
